// Legacy compatibility module: no production HTML entry loads this UI. Active pages use state-sync.js and qinghe_arg_save.
import {recordTable} from './record-table.js?v=43';
import {legacyNetworkRoute} from './network-engine.js?v=43';
import {hintMarkup} from './investigation.js?v=43';
import {EXP_STEPS,EXP_RELATIONS,EXP_EDGES,EXP_DOC_GATES,edgeKey,canAccessExpansionDoc,collectExpansionDoc,recoverStaffAccount,loginStaffAccount,solveExpansion,linkEvidence,chooseExpansionEnding} from './expansion-engine.js?v=43';
import {archiveChapters,archiveDocs,cacheFragments,archiveHints,archiveEndings} from './expansion-content.js?v=43';
import {decryptArchive,workbookBlob} from './archive-crypto.js?v=43';

export function createArchive({getState,save,view,heading,esc,toast,showReader,render}){
 let selected=[],fragments=[],decrypted=null,typingTimer,soundContext;
 const current=()=>getState().expansion;
 const ready=()=>getState().caseSolved;
 const href=id=>legacyNetworkRoute('archive',id)||'#archive/'+id;
 const docLink=id=>`<a class="archive-doc-link" href="${href(id)}"><span>↗</span><strong>${esc(archiveDocs[id].title)}</strong><small>${current().evidence.includes(id)?'已保存副本':archiveDocs[id].summary}</small></a>`;
 const table=(d,kind='')=>recordTable(d,{choice:kind,key:kind||'archive',selected:getState().network?.tableMarks[kind]||[]});
 const select=(name,title,opts)=>`<label class="case-field"><span>${title}</span><select name="${name}" required><option value="">请选择</option>${opts.map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></label>`;
 const feedback=()=>'<p class="archive-feedback" role="status" id="archiveFeedback"></p>';
 function toolbar(){return `<div class="archive-toolbar"><a href="#annex/${13+current().stage}">继续调查</a><a href="#staff-login">小范的阅览账号</a><a href="#board">证据连线</a><label><input type="checkbox" data-archive-sound ${current().sound?'checked':''}> 心跳提示音</label><small>音效默认关闭</small>${current().stage>=1?'<button data-archive-ending="A">先按现有通报结案（A）</button>':''}</div>`;}
 function guard(){view.innerHTML=heading('','这份目录还没交到你手里','先查清第三张投稿图的来历。')+'<a class="primary" href="#notes">回到原案调查</a>';}
 function lock(message){view.innerHTML=heading('','还缺前面的材料',message)+`<a class="primary" href="#annex/${13+current().stage}">回到当前调查</a>`;}
 function result(out){const target=document.querySelector('#archiveFeedback');if(target){target.textContent=out.message;target.classList.toggle('success',out.ok);}if(!out.ok)toast(out.message);}
 function pulse(step,message){if(current().noticed.includes(EXP_STEPS[step]))return;current().noticed.push(EXP_STEPS[step]);save();view.classList.remove('archive-alert');void view.offsetWidth;view.classList.add('archive-alert');setTimeout(()=>view.classList.remove('archive-alert'),1000);clearInterval(typingTimer);const line=document.querySelector('[data-archive-revelation]');if(line){line.replaceChildren();const sr=document.createElement('span');sr.className='archive-sr';sr.textContent=message;const text=document.createElement('span');text.setAttribute('aria-hidden','true');line.append(sr,text);if(globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches)text.textContent=message;else{let i=0;typingTimer=setInterval(()=>{text.textContent=message.slice(0,++i);if(i>=message.length)clearInterval(typingTimer);},70);}}
  if(current().sound){try{const Context=window.AudioContext||window.webkitAudioContext;if(Context){const audio=soundContext||(soundContext=new Context());audio.resume().catch(()=>{});for(const offset of [0,.19,.65,.84]){const oscillator=audio.createOscillator(),gain=audio.createGain();oscillator.frequency.value=68;gain.gain.setValueAtTime(0,audio.currentTime+offset);gain.gain.linearRampToValueAtTime(.10,audio.currentTime+offset+.025);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+offset+.13);oscillator.connect(gain);gain.connect(audio.destination);oscillator.start(audio.currentTime+offset);oscillator.stop(audio.currentTime+offset+.15);}}}catch{toast('声音暂不可用，文字提示已保留。');}}
 }
 function completed(step){save();document.dispatchEvent(new CustomEvent('qinghe:evidence-confirmed',{detail:{kind:'archive',step}}));const after=document.querySelector('#archiveAfter');if(after)after.hidden=false;pulse(step,['阅览目录里，留着一封没发出去的信。','“全程在场”不是那晚自动留下的记录。','先到的复查结果，没有进入后出的汇总。','同一封信，旧结尾和新结尾说的不是一回事。','停电的半小时，在表里一直亮着。','五组材料接上了。剩下的要交给原件复核。'][step]);}
 function chapter(number){const step=number-13;if(!Number.isInteger(step)||step<0||step>6||step>current().stage)return lock('按章节顺序查阅。所有口令线索和旧材料都能重读。');const c=archiveChapters[step];view.innerHTML=toolbar()+`<div class="chapter-breadcrumb"><a href="#notes">调查笔记</a><span>第 ${number} / 19 章</span></div><section class="chapter-heading"><small>${c.date}</small><h1>${c.title}</h1></section><article class="chapter-story">${c.story}</article><nav class="archive-doc-grid">${c.docs.map(docLink).join('')}</nav>`;
  if(step===6){view.insertAdjacentHTML('beforeend',`<section class="case-workbench"><h2>这份材料怎么交</h2><p>五组证据齐全，可提交去标识副本并等待原件复核。选择A仍可回头补证。</p><button class="primary" data-archive-ending="B">B · 提交完整材料，要求公开复核</button> <button class="secondary" data-archive-ending="A">A · 到此为止，接受现有通报</button>${feedback()}</section>`);return;}
  const done=step<current().stage;view.insertAdjacentHTML('beforeend',`<section class="case-workbench archive-workbench"><h2>${['找回小范授权的阅览账号','用名册筛选记录，再核对时间与签认人','哪一份阴性不能直接用于排除','按同一版本恢复草稿正文','解开L-0313加密附件','把文书之间的关系说清楚'][step]}</h2>${done?'<p class="step-done">✓ 已核对，可重新查看资料。</p>':''}${puzzle(step)}${feedback()}<p class="archive-revelation" data-archive-revelation></p><section id="archiveAfter" ${done?'':'hidden'}><article class="chapter-after">${c.after}</article><a class="primary" href="#annex/${number+1}">接着看：${archiveChapters[step+1].title} →</a></section></section>`);}
 function puzzle(step,embedded=false){if(step===1&&!embedded)return '<p>资料已同步到后勤核查工作台。</p><a class="primary" href="#portal/timeline">进入后勤系统核对原始表格 →</a>';if(step===0)return '<a class="primary" href="#recover">按密保找回账号</a> <a class="secondary" href="#staff-login">已有阅览口令，去登录</a>';
  if(step===1)return `<form data-archive-step="1"><p>先从名册选出需要追问的登记，再在另外三表各选一行。班级、卡片前缀、批准时段和撤销状态都要核对。</p>${table(archiveDocs.roster,'roster')}${table(archiveDocs.swipe,'swipe')}${table(archiveDocs.attendance,'attendance')}${table(archiveDocs.signoff,'signoff')}${select('explanation','这组材料支持哪种解释？',[['infection','证明王原导致感染'],['borrow','卡借出，所有材料都不必再核对'],['proxy','到过食堂；“全程在场”系事后代填']])}<button class="primary">提交这组时间线质疑</button></form>`;
  if(step===2)return `<form data-archive-step="2">${table(archiveDocs.medical)}${table(archiveDocs.medication)}${select('patient','需要重新核对初检可靠性的记录',[['by','by'],['yida','益达'],['R07','R07']])}<label class="case-field"><span>该记录后续复查的月日</span><input name="repeat" placeholder="例如0329" maxlength="12" required></label>${select('interpretation','初检能说明什么？',[['unreliable','受检测前用药影响，不能凭这次阴性排除'],['safe','数值低，所以肯定没有感染'],['new','复查阳性证明最近刚感染']])}${select('batch','能否用DOB和用药日期推算感染批次？',[['unknown','不能；只能核对检测可靠性和材料收文顺序'],['school','可以确认学校内传播'],['order','可以按DOB高低排列感染先后']])}<button class="primary">核对报告与汇总</button></form>`;
  if(step===3)return '<p>邮箱里显示半封信。查看同编号的本地缓存，按版本恢复。</p><a class="primary" href="#mailbox">打开授权的草稿箱副本</a>';
  if(step===4)return '<div class="archive-error"><strong>预览失败：文件可能损坏</strong><p>ERR_PREVIEW_NO_KEY · .enc附件需要口令，原件未损坏。</p></div><a class="primary" href="#portal/ledger">使用附件解锁页</a>';
  return '<p>把这一章六份材料保存后，在证据板上点选两张卡，选择关系，提出质疑。需完成五组互证。</p><a class="primary" href="#board">打开证据板</a>';
 }
 function documentPage(id){const d=archiveDocs[id];if(!d)return lock('没有找到这个附件。');if(!canAccessExpansionDoc(getState(),id)){if(current().stage>=EXP_DOC_GATES[id]){view.innerHTML=toolbar()+heading('','需要登录阅览副本','已经保存过的材料不必重新登录。')+'<a class="primary" href="#staff-login">登录小范的授权账号</a>';return;}return lock('先完成前一章，目录中才会出现这份材料。');}
  const s=current();view.innerHTML=toolbar()+`<a class="back-link" href="#annex/${13+s.stage}">← 回到当前调查</a>`+heading('',d.title,d.summary)+`<article class="archive-paper"><div class="archive-paper-stamp">青禾校园网 · 剧情虚构资料</div>${d.image?`<img class="archive-photo" src="${d.image}" alt="${esc(d.summary)}">`:''}${d.body}${d.columns?table(d):''}${d.vault?(s.workbook?table({...s.workbook,title:'L-0313 消杀台账'}):'<p>文件已经解锁。为再次查看原件或下载，请回解锁页重新载入。</p>'):''}<button class="collect-button ${s.evidence.includes(id)?'collected':''}" data-archive-collect="${id}">${s.evidence.includes(id)?'✓ 已保存副本':'＋ 保存到资料和证据板'}</button></article>${id==='cache'?'<a class="primary" href="#mailbox">查看缓存残片</a>':id==='blackboard'||id==='ledger'?'<a class="primary" href="#portal/ledger">打开附件解锁页</a>':''}`;
 }
 function recover(){view.innerHTML=toolbar()+heading('','找回授权阅览账号','账号：xiaofan · 按授权找回临时阅览口令')+`<section class="archive-recovery"><p>小范已授权使用本副本。先读并保存授权、旧帖和排期，再回答密保。</p><nav class="archive-doc-grid">${['authorization','oldpost','radio'].map(docLink).join('')}</nav><form id="archiveRecovery"><label class="case-field"><span>第一次值班那天，晚自习广播最后一首是什么？</span><input name="answer" autocomplete="off" maxlength="50" required><small>可直接填写，也可从下面的旧节目里选一首。</small></label><fieldset class="recovery-options"><legend>节目单中出现过的末曲（按值班日期核对）</legend><label><input type="radio" name="song" value="平凡之路">平凡之路</label><label><input type="radio" name="song" value="稻香">稻香</label><label><input type="radio" name="song" value="夜空中最亮的星">夜空中最亮的星</label></fieldset><button class="primary">找回临时阅览口令</button></form>${feedback()}${current().recovered?'<div class="archive-token"><p>临时阅览口令：<strong>sz-read-0331</strong></p><a class="primary" href="#staff-login">用xiaofan登录</a></div>':''}</section>`;}
 function login(){view.innerHTML=toolbar()+heading('','小范的授权资料柜','只读账号；授权范围见小范的邮件')+`<form id="archiveLogin" class="account-form" autocomplete="off"><label>账号<input name="username" value="xiaofan" required></label><label>临时阅览口令<input name="password" type="password" required></label><button class="primary">登录阅览副本</button><a class="back-link" href="#recover">忘记口令？按授权密保找回</a>${feedback()}</form>${current().loggedIn?'<div class="step-done">✓ 当前已登录 <button class="secondary" data-archive-logout>退出阅览账号</button><a class="primary" href="#annex/14">查看资料目录 →</a></div>':''}<p data-archive-revelation></p><div id="archiveAfter" hidden><a class="primary" href="#annex/14">继续：全班都在，少了一个人 →</a></div>`;}
 function mailbox(){if(current().stage<3)return lock('先核对健康汇总，再看这封信的残片。');if(!canAccessExpansionDoc(getState(),'cache'))return documentPage('cache');view.innerHTML=toolbar()+heading('','校园邮箱 · 本地草稿副本','小范主动导出的离线副本，仅含本次授权材料')+`<div class="archive-mailbox"><aside><strong>草稿箱</strong><p>D0329 / 未发送</p><p>附件载入失败</p><a href="#archive/cache">导出说明</a></aside><article><header><strong>请不要用空白抽检单结算</strong><p>收件人：后勤核查工作邮箱（虚构）</p></header><p>JK-0330-07已经签收，不应继续写无新增待核材料。</p><div class="archive-error">正文在此截断。重试发送不能找回旧版本；可查看本地自动保存残留。</div><p>先<a href="#archive/cache">保存缓存说明</a>，再选择修订02的首尾两段。本副本仅供恢复，发送功能已停用。</p></article></div><section class="case-workbench"><h2>自动保存残片</h2><div class="archive-fragments">${cacheFragments.map(f=>`<button class="archive-fragment ${fragments.includes(f.id)?'selected':''}" data-archive-fragment="${f.id}" aria-pressed="${fragments.includes(f.id)}"><small>${f.draft} / 修订${f.revision} / 段${f.part} / ${f.time}</small><p>${f.text}</p></button>`).join('')}</div><p>已选顺序：${fragments.length?fragments.map(id=>{const f=cacheFragments.find(x=>x.id===id);return `${f.draft}/${f.revision}/${f.part}`;}).join(' → '):'尚未选择'}</p><button class="secondary" data-archive-clear-fragments>清空重排</button> <button class="primary" data-archive-restore>恢复这两段</button>${feedback()}<p data-archive-revelation></p><div id="archiveAfter" ${current().restored?'':'hidden'}><article class="archive-restored"><h3>D0329 / 修订02 · 恢复正文</h3>${cacheFragments.filter(f=>f.id==='d2-head'||f.id==='d2-tail').sort((a,b)=>a.part.localeCompare(b.part)).map(f=>`<p>${f.text}</p>`).join('')}<small>仅从现存残片恢复；保留原版本号。</small></article><a class="primary" href="#annex/17">继续：黑板上的旧日期 →</a></div></section>`;}
 function vault(){if(current().stage<4)return lock('恢复完整草稿以后，才能确定附件的出处。');view.innerHTML=toolbar()+heading('','L-0313 · 加密附件','Excel导出包 / 输入口令解密后，可预览并下载.xlsx原件')+`<section class="case-workbench"><div class="archive-error"><strong>浏览器直接预览失败</strong><p>ERR_PREVIEW_NO_KEY。附件需要口令，反复刷新不会解开。</p></div>${docLink('blackboard')}<form id="archiveVault"><label class="case-field"><span>旧黑板报上，夜宵窗口试运行的八位日期</span><input name="password" type="password" inputmode="numeric" maxlength="12" required></label><button class="primary">解密并核对附件</button></form>${feedback()}<p data-archive-revelation></p><div id="archiveAfter" ${current().vault?'':'hidden'}>${current().workbook?table({...current().workbook,title:'L-0313 消杀台账'}):''}<p>附件验证已通过。刷新后可再次预览、下载。</p><button class="secondary" data-archive-download ${current().workbook?'':'disabled'}>下载L-0313_消杀台账.xlsx</button> <a class="primary" href="#annex/18">接着看：合格的那一栏 →</a></div></section>`;}
 function board(){const s=current();if(s.stage<5)return lock('先解锁加密附件，再把本次记录放上证据板。');const held=s.evidence.filter(id=>EXP_EDGES.some(e=>e.from===id||e.to===id));const ordering=['medical','contract','outage','lab-edited','swipe','ledger','summary','settlement','attendance','lab-original'];view.innerHTML=toolbar()+heading('','证据板','点击两张卡片，再选关系。可用键盘操作；连线结果也保留文字说明。')+`<p>两份证据被放到一起，不代表一定相关。请核对同一个人、时间、文号或付款依据。</p><div class="archive-board" id="archiveBoard"><svg aria-hidden="true" class="archive-wires" id="archiveWires"></svg><div class="archive-cards">${ordering.filter(id=>held.includes(id)).map(id=>`<button class="archive-evidence ${selected.includes(id)?'selected':''}" data-archive-node="${id}" aria-pressed="${selected.includes(id)}"><small>已保存副本</small><strong>${esc(archiveDocs[id].title)}</strong><span>${esc(archiveDocs[id].summary)}</span></button>`).join('')}</div></div><section class="case-workbench"><h2>提出一组质疑</h2><p id="archiveSelected">${selected.length?selected.map(id=>esc(archiveDocs[id].title)).join(' → '):'先点选两份证据。'}</p><form id="archiveLink">${select('relation','这两份材料是什么关系？',Object.entries(EXP_RELATIONS))}<button class="primary">连线并核对</button><button type="button" class="secondary" data-archive-clear-nodes>清空选择</button></form>${feedback()}<p data-archive-revelation></p><h3>已核实 ${s.links.length} / ${EXP_EDGES.length} 组关系</h3><ol class="archive-link-list">${EXP_EDGES.filter(e=>s.links.includes(edgeKey(e))).map(e=>`<li>${esc(archiveDocs[e.from].title)} <b>${EXP_RELATIONS[e.relation]}</b> ${esc(archiveDocs[e.to].title)}<p>${e.label}</p><button class="small-text" data-archive-unlink="${esc(edgeKey(e))}">移除连线，重新核对</button></li>`).join('')}</ol><button class="primary" data-archive-submit-board>整理完整问题清单</button><div id="archiveAfter" ${s.stage>=6?'':'hidden'}><p>五组材料已齐。下一步交付去标识副本，由原出具单位、设备与财务记录复核。</p><a class="primary" href="#annex/19">继续：公告贴上去以后 →</a></div></section><details class="chapter-directory"><summary>还缺哪些副本？从这里回去取</summary>${Object.keys(archiveDocs).filter(id=>EXP_DOC_GATES[id]<=s.stage&&!s.evidence.includes(id)).map(docLink).join('')||'本次目录均已保存。'}</details>`;requestAnimationFrame(drawWires);}
 function drawWires(){const box=document.querySelector('#archiveBoard'),svg=document.querySelector('#archiveWires');if(!box||!svg)return;const base=box.getBoundingClientRect();svg.setAttribute('viewBox',`0 0 ${base.width} ${base.height}`);svg.innerHTML=EXP_EDGES.filter(e=>current().links.includes(edgeKey(e))).map(e=>{const a=box.querySelector(`[data-archive-node="${e.from}"]`)?.getBoundingClientRect(),b=box.querySelector(`[data-archive-node="${e.to}"]`)?.getBoundingClientRect();if(!a||!b)return '';const x1=a.left+a.width/2-base.left,y1=a.top+a.height/2-base.top,x2=b.left+b.width/2-base.left,y2=b.top+b.height/2-base.top;return `<path d="M${x1},${y1} Q${(x1+x2)/2+25},${(y1+y2)/2-30} ${x2},${y2}" class="wire-${e.relation}"/>`;}).join('');}
 window.addEventListener('resize',drawWires);
 function outcome(which){if(!['A','B'].includes(which)||!current().visitedEndings.includes(which))return lock('结局需要在调查中作出选择，直接打开链接不会提前解锁。');const e=archiveEndings[which];view.innerHTML=toolbar()+heading('',e.title,e.subtitle)+`<article class="chapter-story resolution-story">${e.body}</article><section class="case-summary"><p>这是一部虚构作品。结局中的公共措施来自文书和原件复核，不代表查明了幽门感染源。</p><p>已经走过：${current().visitedEndings.join('、')}；证据关系 ${current().links.length}/5。</p><a class="primary" href="#annex/${13+current().stage}">${which==='A'?'保留进度，继续补证':'回看最后一章'}</a> <a class="secondary" href="#board">回看证据板</a> <a class="secondary" href="#resolution">回看朱贵与宿舍的原案尾声</a></section>`;}
 function handleRoute(section,id){if(!['annex','archive','recover','staff-login','mailbox','vault','board','outcome'].includes(section))return false;if(!ready()){guard();return true;}switch(section){case 'annex':chapter(Number(id)||13);break;case 'archive':documentPage(id);break;case 'recover':recover();break;case 'staff-login':login();break;case 'mailbox':mailbox();break;case 'vault':vault();break;case 'board':board();break;case 'outcome':outcome(id);break;}return true;}
 function decorate(section){if(!ready()||!['forum','notes','files','resolution','accounts'].includes(section))return;view.insertAdjacentHTML('afterbegin',`<section class="archive-entry"><div><small>后续篇 · 第13—19章</small><h2>${current().stage===6?'公告贴上去以后':archiveChapters[current().stage].title}</h2><p>那份“个人卫生问题”的通报，还缺谁的签名？</p></div><a class="primary" href="#annex/${13+current().stage}">${current().stage?'继续后续调查':'打开小范留下的目录'} →</a></section>`);if(section==='files')view.insertAdjacentHTML('beforeend',`<h2 class="file-section-title">我保存的后续副本</h2><div class="archive-doc-grid">${current().evidence.map(docLink).join('')}</div>`);if(section==='notes')view.insertAdjacentHTML('beforeend',`<section class="case-summary"><h2>后勤调查 · ${current().stage}/6 组核对</h2><a class="primary" href="#board">证据连线 / 矛盾质疑</a><details class="chapter-directory"><summary>后续篇章节</summary>${archiveChapters.filter((_,i)=>i<=current().stage).map(c=>`<a href="#annex/${c.number}">第${c.number}章　${c.title}</a>`).join('')}</details>${['A','B'].filter(e=>current().visitedEndings.includes(e)).map(e=>`<a class="secondary" href="#outcome/${e}">重读结局${e}</a>`).join('')}</section>`);}
 function hints(advance=false){if(!ready())return false;const step=current().stage;if(advance===true)current().hint=Math.min(2,current().hint+1);save();showReader('后续调查提示',hintMarkup(archiveChapters[step].title,archiveHints[step],current().hint,'第'+(13+step)+'章'));return true;}
 function searchEntries(){if(!ready())return [];return Object.entries(archiveDocs).filter(([id])=>canAccessExpansionDoc(getState(),id)).map(([id,d])=>({title:d.title,summary:d.summary,keywords:[id,'小范',...(id==='oldpost'||id==='radio'?['密保','广播','第一次值班']:[])],type:'后续资料',route:href(id)}));}
 document.addEventListener('change',e=>{if(e.target.matches('#archiveRecovery input[name=song]'))e.target.form.elements.answer.value=e.target.value;if(e.target.matches('[data-archive-sound]')){current().sound=e.target.checked;if(current().sound){try{const Context=window.AudioContext||window.webkitAudioContext;if(Context){soundContext=soundContext||new Context();soundContext.resume().catch(()=>{});}}catch{}}else if(soundContext){soundContext.close().catch(()=>{});soundContext=null;}save();toast(current().sound?'已开启短暂心跳提示音。':'提示音已关闭。');}});
 document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||!ready())return;
  if(b.dataset.archiveCollect){if(collectExpansionDoc(getState(),b.dataset.archiveCollect)){save();b.textContent='✓ 已保存副本';b.classList.add('collected');toast('已保存：'+archiveDocs[b.dataset.archiveCollect].title);}return;}
  if(b.hasAttribute('data-archive-logout')){current().loggedIn=false;save();login();return;}
  if(b.dataset.archiveFragment){const id=b.dataset.archiveFragment;fragments=fragments.includes(id)?fragments.filter(v=>v!==id):[...fragments.slice(-1),id];mailbox();return;}
  if(b.hasAttribute('data-archive-clear-fragments')){fragments=[];mailbox();return;}
  if(b.hasAttribute('data-archive-restore')){const r=solveExpansion(getState(),3,{fragments});result(r);if(r.ok){completed(3);}return;}
  if(b.dataset.archiveNode){const id=b.dataset.archiveNode;selected=selected.includes(id)?selected.filter(v=>v!==id):[...selected.slice(-1),id];board();return;}
  if(b.hasAttribute('data-archive-clear-nodes')){selected=[];board();return;}
  if(b.dataset.archiveUnlink){if(current().stage>=6){toast('已提交的清单保留原线；可以回看证据出处。');return;}current().links=current().links.filter(v=>v!==b.dataset.archiveUnlink);save();board();return;}
  if(b.hasAttribute('data-archive-submit-board')){const r=solveExpansion(getState(),5);result(r);if(r.ok)completed(5);return;}
  if(b.dataset.archiveEnding){const r=chooseExpansionEnding(getState(),b.dataset.archiveEnding);result(r);if(r.ok){save();location.hash='#outcome/'+b.dataset.archiveEnding;}return;}
  if(b.hasAttribute('data-archive-download')&&current().workbook){const url=URL.createObjectURL(workbookBlob(current().workbook)),a=document.createElement('a');a.href=url;a.download='L-0313_消杀台账.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 });
 document.addEventListener('submit',async e=>{const form=e.target;if(!['archiveRecovery','archiveLogin','archiveVault','archiveLink'].includes(form.id)&&!form.hasAttribute('data-archive-step'))return;e.preventDefault();if(!ready())return;const data=new FormData(form);
  if(form.id==='archiveRecovery'){const r=recoverStaffAccount(getState(),data.get('answer'));if(r.ok){save();recover();}result(r);return;}
  if(form.id==='archiveLogin'){const r=loginStaffAccount(getState(),data.get('username'),data.get('password'));result(r);if(r.ok){completed(0);toast('阅览账号已登录，继续查看目录。');}return;}
  if(form.id==='archiveLink'){const r=linkEvidence(getState(),selected[0],selected[1],data.get('relation'));if(r.ok){save();board();}result(r);return;}
  if(form.hasAttribute('data-archive-step')){const step=Number(form.dataset.archiveStep),r=solveExpansion(getState(),step,Object.fromEntries(data));result(r);if(r.ok)completed(step);return;}
  if(form.id==='archiveVault'){const stateAtStart=getState(),submit=form.querySelector('button');submit.disabled=true;result({ok:true,message:'正在验证附件…'});try{
    if(!current().evidence.includes('blackboard'))throw new Error('先保存黑板报，给口令留下出处。');
    let response;try{response=await fetch(new URL('./assets/L-0313.enc.json',import.meta.url));}catch{throw new Error('附件暂未载入，请检查网络后重试。');}if(!response.ok)throw new Error('附件载入失败，请稍后重试。');
    const envelope=await response.json();try{decrypted=await decryptArchive(envelope,data.get('password'));}catch(error){if(error.name==='OperationError')throw new Error('口令不对，附件未解开。看看试运行对应的日期。');throw error;}
    if(stateAtStart!==getState())return;const r=solveExpansion(getState(),4,{decrypted:true});if(r.ok){current().workbook=decrypted;save();if(form.isConnected){if(location.hash==='#portal/ledger')render();else vault();result(r);completed(4);}else toast('附件已解锁，可从资料页继续。');}else result(r);
   }catch(error){if(form.isConnected)result({ok:false,message:error.message||'暂时未能解开附件，请重试。'});}finally{if(form.isConnected)submit.disabled=false;}}
 });
 return {handleRoute,decorate,hints,searchEntries,timelineMarkup:()=>puzzle(1,true),status:()=>ready()?'后续调查 · 第'+(13+current().stage)+'章 · '+archiveChapters[current().stage].title:null,reset:()=>{selected=[];fragments=[];decrypted=null;clearInterval(typingTimer);if(soundContext){soundContext.close().catch(()=>{});soundContext=null;}}};
}
